// Package ratelimit implements a concurrency-safe token-bucket rate limiter.
package ratelimit

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

// Clock reports the current time. It is injectable for testing.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock returns a Clock backed by time.Now.
func RealClock() Clock { return realClock{} }

// Limiter is a concurrency-safe token-bucket rate limiter.
// A Limiter must be created by New; the zero value is not usable.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	last     time.Time
	rate     float64 // tokens per second
	burst    float64
	maxBurst int64
	clock    Clock
}

// ErrInvalidConfig is returned by New for non-positive rate or burst.
var ErrInvalidConfig = errors.New("ratelimit: rate and burst must be positive")

// New returns a Limiter that emits rate tokens per second, holding at most
// burst tokens. The bucket starts full.
func New(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, fmt.Errorf("%w: rate=%v", ErrInvalidConfig, rate)
	}
	if burst <= 0 {
		return nil, fmt.Errorf("%w: burst=%d", ErrInvalidConfig, burst)
	}
	if clock == nil {
		clock = RealClock()
	}
	now := clock.Now()
	return &Limiter{
		tokens: float64(burst),
		last:   now,
		rate:   rate,
		burst:  float64(burst),
		clock:  clock,
	}, nil
}

// Allow reports whether n tokens are available at the current time.
// It is equivalent to AllowN(clock.Now(), n).
func (l *Limiter) Allow(n int) bool {
	return l.AllowN(l.clock.Now(), n)
}

// AllowN reports whether n tokens may be consumed at time t.
// If n exceeds the burst capacity, AllowN returns false and the bucket
// is left unchanged. Otherwise, if n tokens are available, they are
// consumed and AllowN returns true; if fewer than n are available,
// AllowN returns false and the bucket is left unchanged.
func (l *Limiter) AllowN(t time.Time, n int) bool {
	if n <= 0 {
		return true
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	l.advance(t)
	need := float64(n)
	if need > l.burst {
		return false
	}
	if l.tokens < need {
		return false
	}
	l.tokens -= need
	return true
}

// Tokens returns the number of tokens currently available, advanced to now.
func (l *Limiter) Tokens() float64 {
	return l.TokensAt(l.clock.Now())
}

// TokensAt returns the number of tokens available at time t, without consuming.
func (l *Limiter) TokensAt(t time.Time) float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(t)
	return l.tokens
}

// advance refills tokens based on elapsed time since the last update.
// It must be called with l.mu held, and t must not precede l.last.
func (l *Limiter) advance(t time.Time) {
	if t.Before(l.last) {
		return
	}
	elapsed := t.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = min(l.burst, l.tokens+elapsed*l.rate)
	}
	l.last = t
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
