package ratelimit

import (
	"errors"
	"testing"
	"time"
)

// fakeClock is a manually advanced Clock for deterministic tests.
type fakeClock struct {
	t time.Time
}

func (c *fakeClock) Now() time.Time { return c.t }
func (c *fakeClock) advance(d time.Duration) {
	c.t = c.t.Add(d)
}

func TestNewValidation(t *testing.T) {
	tests := []struct {
		name    string
		rate    float64
		burst   int
		wantErr bool
	}{
		{"ok", 1, 1, false},
		{"zero rate", 0, 10, true},
		{"negative rate", -1.5, 10, true},
		{"zero burst", 10, 0, true},
		{"negative burst", 10, -3, true},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			l, err := New(tc.rate, tc.burst, nil)
			if tc.wantErr {
				if err == nil {
					t.Fatalf("New(%v, %d) = nil error, want error", tc.rate, tc.burst)
				}
				if !errors.Is(err, ErrInvalidConfig) {
					t.Fatalf("error = %v, want ErrInvalidConfig", err)
				}
				return
			}
			if err != nil {
				t.Fatalf("New(%v, %d) unexpected error: %v", tc.rate, tc.burst, err)
			}
			if l == nil {
				t.Fatal("New returned nil Limiter with nil error")
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	start := time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)

	tests := []struct {
		name  string
		rate  float64
		burst int
		steps []struct {
			advance time.Duration // before the call
			n       int
			want    bool
		}
		wantTokens float64 // final TokensAt value; -1 to skip check
	}{
		{
			name: "burst consumed then denied",
			rate: 1, burst: 3,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 3, true},
				{0, 1, false},
			},
			wantTokens: 0,
		},
		{
			name: "refill over time",
			rate: 1, burst: 2,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 2, true},
				{2 * time.Second, 1, true},
				{0, 1, false},
			},
			wantTokens: 0,
		},
		{
			name: "partial refill insufficient",
			rate: 1, burst: 2,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 2, true},
				{500 * time.Millisecond, 1, false},
				{500 * time.Millisecond, 1, true},
			},
			wantTokens: 0,
		},
		{
			name: "n exceeds burst denied without change",
			rate: 1, burst: 2,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 3, false},
				{0, 2, true},
			},
			wantTokens: 0,
		},
		{
			name: "tokens capped at burst",
			rate: 10, burst: 2,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 2, true},
				{10 * time.Second, 2, true},
			},
			wantTokens: 0,
		},
		{
			name: "non-positive n allowed",
			rate: 1, burst: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 0, true},
				{0, -1, true},
				{0, 1, true},
			},
			wantTokens: 0,
		},
		{
			name: "fractional refill accumulates",
			rate: 2, burst: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true},
				{250 * time.Millisecond, 1, false},
				{250 * time.Millisecond, 1, true},
			},
			wantTokens: 0,
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			clk := &fakeClock{t: start}
			l, err := New(tc.rate, tc.burst, clk)
			if err != nil {
				t.Fatalf("New: %v", err)
			}
			for i, s := range tc.steps {
				clk.advance(s.advance)
				if got := l.AllowN(clk.Now(), s.n); got != s.want {
					t.Fatalf("step %d: AllowN(%d) = %v, want %v", i, s.n, got, s.want)
				}
			}
			if tc.wantTokens >= 0 {
				if got := l.TokensAt(clk.Now()); got != tc.wantTokens {
					t.Fatalf("TokensAt = %v, want %v", got, tc.wantTokens)
				}
			}
		})
	}
}

func TestAllowUsesClock(t *testing.T) {
	clk := &fakeClock{t: start}
	l, err := New(1, 1, clk)
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	if !l.Allow(1) {
		t.Fatal("first Allow(1) = false, want true")
	}
	if l.Allow(1) {
		t.Fatal("second Allow(1) = true, want false")
	}
	clk.advance(time.Second)
	if !l.Allow(1) {
		t.Fatal("Allow(1) after refill = false, want true")
	}
}

func TestTokensAtDoesNotConsume(t *testing.T) {
	clk := &fakeClock{t: start}
	l, err := New(1, 5, clk)
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	for i := 0; i < 3; i++ {
		if got := l.TokensAt(clk.Now()); got != 5 {
			t.Fatalf("TokensAt = %v, want 5", got)
		}
	}
	if !l.AllowN(clk.Now(), 5) {
		t.Fatal("AllowN(5) = false, want true")
	}
}

func TestConcurrentAccess(t *testing.T) {
	clk := &fakeClock{t: start}
	l, err := New(1000, 100, clk)
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	const goroutines = 50
	const perG = 3
	allowed := make(chan bool, goroutines*perG)
	var wg syncWaitGroup
	wg.Add(goroutines)
	for i := 0; i < goroutines; i++ {
		go func() {
			defer wg.Done()
			for j := 0; j < perG; j++ {
				allowed <- l.Allow(1)
			}
		}()
	}
	wg.Wait()
	close(allowed)
	granted := 0
	for ok := range allowed {
		if ok {
			granted++
		}
	}
	if granted > 100 {
		t.Fatalf("granted %d tokens, want <= burst (100)", granted)
	}
	if granted == 0 {
		t.Fatal("granted 0 tokens, want some")
	}
}

